//! The embedded zone set (E13.F02.S01.T04): TZif bytes of every IANA zone
//! a Windows zone maps to, generated by `zig build tzdata-gen` (format in
//! tools/tzdata_gen/main.zig). Only Windows builds (and tests) embed it;
//! elsewhere zones come from the zoneinfo directory and `find` is null.

const std = @import("std");
const builtin = @import("builtin");

const blob: []const u8 = if (builtin.os.tag == .windows or builtin.is_test) @embedFile("tzdata/zones.bin") else "";

pub const Entry = struct { name: []const u8, data: []const u8 };

pub const Iterator = struct {
    i: usize,
    left: u16,

    pub fn next(it: *Iterator) ?Entry {
        if (comptime blob.len == 0) return null;
        if (it.left == 0) return null;
        it.left -= 1;
        const n = blob[it.i];
        const name = blob[it.i + 1 ..][0..n];
        const p = blob[it.i + 1 + n ..][0..8];
        it.i += 1 + n + 8;
        const off = std.mem.readInt(u32, p[0..4], .little);
        const len = std.mem.readInt(u32, p[4..8], .little);
        return .{ .name = name, .data = blob[off..][0..len] };
    }
};

/// The tzdata release, or "" when nothing is embedded.
pub fn version() []const u8 {
    if (comptime blob.len < 9) return "";
    return blob[9..][0..blob[8]];
}

pub fn iterator() Iterator {
    if (blob.len < 9 or !std.mem.eql(u8, blob[0..4], "ZGTZ")) return .{ .i = 0, .left = 0 };
    return .{ .i = 9 + blob[8], .left = std.mem.readInt(u16, blob[6..8], .little) };
}

pub fn find(name: []const u8) ?[]const u8 {
    var it = iterator();
    while (it.next()) |e| if (std.mem.eql(u8, e.name, name)) return e.data;
    return null;
}
